    // all output channels and all output positions within the tile.
    __shared__ float s_input[CIN][SH][SH];
    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;
    int wsize = COUT * CIN * K * K;
    for (int i = tid; i < wsize; i += nthreads) {
        s_weight[i] = __bfloat162float(weight[i]);
