    // along the width dimension into a single __nv_bfloat162 load,
    // halving the number of global memory transactions and improving
    // coalescing compared to scalar bf16 loads.
    int SH_half = SH / 2; // SH is even (TILE + K - 1 = 18)
    int load_total_half = CIN * SH * SH_half;
    for (int i = tid; i < load_total_half; i += nthreads) {
        int tmp = i;
        int sw2 = tmp % SH_half; tmp /= SH_half;
        int sh = tmp % SH; tmp /= SH;
        int ci = tmp;
        int sw = sw2 * 2;
        int in_h = ho0 + sh;
        int in_w0 = wo0 + sw;
        int in_w1 = in_w0 + 1;
        float val0 = 0.0f, val1 = 0.0f;
        if (in_h < H) {
            long base_off = (long)ci * H * W + (long)in_h * W + in_w0;
            if (in_w0 < W && in_w1 < W) {
