    // positions, doubling reuse of weights loaded from shared memory
    // compared to computing a single output row per thread.
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int ho_l0 = ty * 2;
    int ho_l1 = ho_l0 + 1;
    int wo_l0 = tx * 2;
    int wo_l1 = wo_l0 + 1;
    int ho_out0 = ho0 + ho_l0;
    int ho_out1 = ho0 + ho_l1;
    int wo_out0 = wo0 + wo_l0;
    int wo_out1 = wo0 + wo_l1;
