    float sum01[COUT];
    float sum10[COUT];
    float sum11[COUT];
    #pragma unroll
    for (int co = 0; co < COUT; co++) {
        sum00[co] = 0.0f; sum01[co] = 0.0f; sum10[co] = 0.0f; sum11[co] = 0.0f;
