        for (int kh = 0; kh < K; kh++) {
            #pragma unroll
            for (int kw = 0; kw < K; kw++) {
                float in00 = s_input[ci][ho_l0 + kh][wo_l0 + kw];
                float in01 = s_input[ci][ho_l0 + kh][wo_l1 + kw];
                float in10 = s_input[ci][ho_l1 + kh][wo_l0 + kw];
                float in11 = s_input[ci][ho_l1 + kh][wo_l1 + kw];
                const float* w_ptr = s_weight + ci * (K * K) + kh * K + kw;
