                for (int co = 0; co < COUT; co++) {
                    float wv = w_ptr[co * (CIN * K * K)];
                    sum00[co] += in00 * wv;
                    sum01[co] += in01 * wv;
                    sum10[co] += in10 * wv;
                    sum11[co] += in11 * wv;
